	error_reporting(0);	

	fncDirList("../Articles");
	fncDirList("../Links");
	
	function fncDirList($dirPath)
		{
			print "<table align='center' cellpadding='0' cellspacing='0' width='96%'>";

			$dirList					= opendir($dirPath);  				
	
			while (($dirPart			= @readdir($dirList)) == true) 
				{  						
					if($dirPart != "." && $dirPart != ".." && $dirPart != "index.php")
						{			
							$tags		= get_meta_tags($dirPath."/".$dirPart);					
							$Title		= str_replace(".php", "", str_replace("_", " ", $dirPart));	
									
							print "<tr><td><a href='".$dirPath."/".$dirPart."'>".$Title."</a><p style=color:#808080;margin-left:0;><small>File Size: ".filesize($dirPath."/".$dirPart)." Bytes | Last Modified: ".date("F d Y H:i:s.", filemtime($dirPath."/".$dirPart))."</small></p><p class='pSiteMap'>".$tags['description']."</p><br></td></tr>";
						}										
				
				} 	
			print "</table>";
		}

?>